<script setup lang="ts">
import {ref,onMounted} from 'vue';import {get,request,newKey} from '../../../../packages/shared/src/client';import {useOperations} from '../../../../packages/shared/src/operations';import {useTask,type Row} from '../../../../packages/shared/src/ui';import type {Operation} from '../../../../packages/shared/src/types';import Status from '../../../../packages/shared/src/Status.vue';
const emit=defineEmits<{saved:[]}>(),task=useTask(),ops=useOperations(),localUpload=ref(false),cloudUpload=ref(false),file=ref<File>(),detectedDuration=ref<number>(),key=ref(newKey());
onMounted(()=>task.run(async()=>{const environment=await get<Row>('/environment');localUpload.value=environment.capabilities?.localUpload===true;cloudUpload.value=environment.capabilities?.cloudUpload===true;}));
function choose(event:Event){file.value=(event.target as HTMLInputElement).files?.[0];detectedDuration.value=undefined;key.value=newKey();}
async function upload(){const done=await task.run(async()=>{if(!localUpload.value || !file.value)return;const form=new FormData();form.set('file',file.value);const operation=await request<Operation>('/admin/media-upload',{method:'POST',body:form},key.value);const result=await ops.track('media','登记本地视频',operation,key.value);if(result.status!=='SUCCEEDED'){task.message.value='视频登记处理中，可刷新后在操作记录中继续查询';return false;}const value=Number((result.result as Row|undefined)?.duration);if(Number.isFinite(value)&&value>0)detectedDuration.value=value;task.message.value='视频已持久化';return true;});if(done)emit('saved');}
</script><template><article class="card"><h3>上传视频</h3><Status :error="task.error.value" :busy="task.busy.value" :message="task.message.value"/><template v-if="localUpload"><el-alert title="本地存储保存真实文件，上传后自动识别视频时长；尚未提供云转码。" type="warning" :closable="false"/><div class="toolbar"><input aria-label="选择本地视频" type="file" accept="video/mp4,video/webm" @change="choose"/><el-button @click="upload" :disabled="!file || task.busy.value">上传并登记</el-button></div><p v-if="detectedDuration">已识别视频时长：{{detectedDuration.toFixed(2)}} 秒</p></template><el-alert v-else-if="!task.busy.value" :title="cloudUpload?'当前页面尚未提供云视频上传，请联系管理员。':'当前环境不支持云视频上传；本地上传也未启用。'" type="info" :closable="false"/></article></template>
